"""
Idempotent curriculum-expansion seed for AtlasCode.

Adds the 10 missing required courses (Databases, JavaScript, Frontend Development,
Backend Development, Full Stack Development, C, C++, Data Structures & Algorithms,
Computer Systems, Networking) on top of the existing 5 courses (Python Foundations,
Web Fundamentals, SQL & Databases, Git & GitHub, CS Fundamentals), which are left
untouched.

Uses the SAME models/architecture as the original seed.py — Course -> Module ->
Lesson -> LessonBlock / Exercise (-> ExerciseOption) — against the live app database
(app.db.session.async_session_maker), not a parallel content system.

Idempotency: every insert is guarded by a lookup on the relevant unique key
(Course.slug / Module(course_id,slug) / Lesson(module_id,slug)). Running this
script multiple times must not create duplicates and must not touch existing rows.

Exercise grading reality check (see app/services/code_executor.py and
app/api/exercises.py): the sandbox only executes Python. So:
  - Python-native courses (Python, Data Structures & Algorithms taught in Python,
    Backend Development using FastAPI/Python) get real `code_writing` exercises
    with working test_code, exactly like the original seed's Python lessons.
  - Courses whose target language the sandbox cannot run (JavaScript, C, C++, and
    conceptual material for Databases/Frontend/Full Stack/Computer Systems/
    Networking) get `multiple_choice` / `prediction` exercises with real
    ExerciseOption rows — the exact pattern the EXISTING SQL & Databases course
    already uses for its non-Python content. No new "looks runnable but always
    fails" exercise type is introduced.
"""
import asyncio
from sqlalchemy import select
from sqlalchemy.orm import selectinload
from app.db.session import async_session_maker
from app.models import (
    Course, CourseTranslation, Module, ModuleTranslation,
    Lesson, LessonTranslation, LessonBlock, LessonBlockTranslation,
    Exercise, ExerciseTranslation, ExerciseOption, ExerciseOptionTranslation,
    LanguageEnum, DifficultyEnum, ExerciseTypeEnum,
)

EN, FR, AR = LanguageEnum.en, LanguageEnum.fr, LanguageEnum.ar
LANGS = (EN, FR, AR)


def py_test(*substrings):
    """Build test_code for a Python code_writing exercise: runs the submitted
    source with exec(), captures stdout, asserts each substring is present."""
    checks = " and ".join(f'{s!r} in output' for s in substrings)
    return (
        'import sys, io; stdout = sys.stdout; sys.stdout = io.StringIO(); '
        'exec(compile(code, "<string>", "exec")); output = sys.stdout.getvalue(); '
        f'sys.stdout = stdout; assert {checks}'
    )


# ---------------------------------------------------------------------------
# Course data
# ---------------------------------------------------------------------------

COURSES = []


def add_course(slug, order, title, desc, skills, modules):
    COURSES.append({
        "slug": slug, "order": order,
        "title": title, "desc": desc, "skills": skills,
        "modules": modules,
    })


def mod(slug, title, desc, lesson):
    return {"slug": slug, "title": title, "desc": desc, "lesson": lesson}


def lesson(slug, title, story, objective, skills, blocks, exercise,
           difficulty="beginner", minutes=25, xp=50):
    return {
        "slug": slug, "title": title, "story": story, "objective": objective,
        "skills": skills, "difficulty": difficulty, "minutes": minutes, "xp": xp,
        "blocks": blocks, "exercise": exercise,
    }


def text_block(content):
    return {"type": "text", "content": content, "code": None}


def code_block(caption, code):
    return {"type": "code", "content": caption, "code": {"en": code, "fr": code, "ar": code}}


def mc_exercise(prompt, hint, explanation, options, xp=15):
    return {
        "kind": "mc", "type": ExerciseTypeEnum.multiple_choice,
        "prompt": prompt, "hint": hint, "explanation": explanation,
        "options": options, "xp": xp,
    }


def prediction_exercise(prompt, hint, explanation, code, answer, xp=15):
    return {
        "kind": "prediction", "type": ExerciseTypeEnum.prediction,
        "prompt": prompt, "hint": hint, "explanation": explanation,
        "code": code, "answer": answer, "xp": xp,
    }


def code_exercise(prompt, hint, explanation, starter, solution, test, xp=20):
    return {
        "kind": "code", "type": ExerciseTypeEnum.code_writing,
        "prompt": prompt, "hint": hint, "explanation": explanation,
        "starter": starter, "solution": solution, "test": test, "xp": xp,
    }


def opt(text, correct=False):
    return {"text": text, "correct": correct}


