# ---------------------------------------------------------------------------

async def seed_curriculum():
    stats = {"courses_created": 0, "modules_created": 0, "lessons_created": 0,
              "exercises_created": 0, "skipped_existing_courses": 0}

    async with async_session_maker() as db:
        for course_data in COURSES:
            existing = await db.execute(select(Course).where(Course.slug == course_data["slug"]))
            course = existing.scalar_one_or_none()

            if course is None:
                course = Course(slug=course_data["slug"], order=course_data["order"])
                db.add(course)
                await db.flush()
                db.add_all([
                    CourseTranslation(course_id=course.id, language=lang,
                                       title=course_data["title"][lang.value],
                                       description=course_data["desc"][lang.value],
                                       skills=course_data["skills"])
                    for lang in LANGS
                ])
                stats["courses_created"] += 1
                print(f"  + course '{course_data['slug']}'")
            else:
                stats["skipped_existing_courses"] += 1
                print(f"  = course '{course_data['slug']}' already exists, skipping")
                continue  # course (and everything under it) already seeded

            for mod_index, mod_data in enumerate(course_data["modules"], start=1):
                mod_existing = await db.execute(
                    select(Module).where(Module.course_id == course.id, Module.slug == mod_data["slug"])
                )
                module = mod_existing.scalar_one_or_none()
                if module is not None:
                    continue

                module = Module(course_id=course.id, slug=mod_data["slug"], order=mod_index)
                db.add(module)
                await db.flush()
                db.add_all([
                    ModuleTranslation(module_id=module.id, language=lang,
                                       title=mod_data["title"][lang.value],
                                       description=mod_data["desc"][lang.value])
                    for lang in LANGS
                ])
                stats["modules_created"] += 1

                ld = mod_data["lesson"]
                lesson_existing = await db.execute(
                    select(Lesson).where(Lesson.module_id == module.id, Lesson.slug == ld["slug"])
                )
                lesson_row = lesson_existing.scalar_one_or_none()
                if lesson_row is not None:
                    continue

                difficulty = {"beginner": DifficultyEnum.beginner, "intermediate": DifficultyEnum.intermediate,
                              "advanced": DifficultyEnum.advanced}[ld["difficulty"]]
                lesson_row = Lesson(module_id=module.id, slug=ld["slug"], order=1,
                                     difficulty=difficulty, estimated_minutes=ld["minutes"], xp_reward=ld["xp"])
                db.add(lesson_row)
                await db.flush()
                db.add_all([
                    LessonTranslation(lesson_id=lesson_row.id, language=lang,
                                       title=ld["title"][lang.value], story=ld["story"][lang.value],
                                       objective=ld["objective"][lang.value], skills=ld["skills"])
                    for lang in LANGS
                ])
                stats["lessons_created"] += 1

                for block_index, block in enumerate(ld["blocks"], start=1):
                    lb = LessonBlock(lesson_id=lesson_row.id, block_type=block["type"], order=block_index,
                                      content=block["content"]["en"],
                                      code_example=(block["code"]["en"] if block["code"] else None))
                    db.add(lb)
                    await db.flush()
                    db.add_all([
                        LessonBlockTranslation(block_id=lb.id, language=lang,
                                                content=block["content"][lang.value],
                                                code_example=(block["code"][lang.value] if block["code"] else None))
                        for lang in LANGS
                    ])

                ex = ld["exercise"]
                if ex["kind"] == "code":
                    exercise = Exercise(lesson_id=lesson_row.id, exercise_type=ex["type"], order=1,
                                         xp_reward=ex["xp"], starter_code=ex["starter"],
                                         solution_code=ex["solution"], test_code=ex["test"])
                elif ex["kind"] == "prediction":
                    exercise = Exercise(lesson_id=lesson_row.id, exercise_type=ex["type"], order=1,
                                         xp_reward=ex["xp"], starter_code=ex["code"], solution_code=ex["answer"])
                else:  # multiple_choice
                    exercise = Exercise(lesson_id=lesson_row.id, exercise_type=ex["type"], order=1,
                                         xp_reward=ex["xp"])
                db.add(exercise)
                await db.flush()
                db.add_all([
                    ExerciseTranslation(exercise_id=exercise.id, language=lang,
                                         prompt=ex["prompt"][lang.value], hint=ex["hint"][lang.value],
                                         explanation=ex["explanation"][lang.value])
                    for lang in LANGS
                ])
                stats["exercises_created"] += 1

                if ex["kind"] == "mc":
                    for opt_index, option in enumerate(ex["options"], start=1):
                        eo = ExerciseOption(exercise_id=exercise.id, order=opt_index, is_correct=option["correct"])
                        db.add(eo)
                        await db.flush()
                        db.add_all([
                            ExerciseOptionTranslation(option_id=eo.id, language=lang, text=option["text"][lang.value])
                            for lang in LANGS
                        ])

            await db.commit()

    return stats


async def main():
    print("Seeding curriculum expansion (idempotent)...")
    stats = await seed_curriculum()
    print("Done.")
    print(stats)


if __name__ == "__main__":
    asyncio.run(main())
